"use strict";gsap.registerPlugin(ScrollTrigger,SplitText);gsap.config({nullTargetWarn:false,trialWarn:false});function pbmit_title_animation(){ScrollTrigger.matchMedia({"(min-width: 1025px)":function(){var pbmit_var=jQuery('.pbmit-custom-heading, .pbmit-heading-subheading');if(!pbmit_var.length){return;}
const quotes=document.querySelectorAll(".pbmit-custom-heading .pbmit-element-title , .pbmit-heading-subheading .pbmit-element-title ");quotes.forEach(quote=>{var getclass=quote.closest('.pbmit-custom-heading ,.pbmit-heading-subheading').className;var animation=getclass.split('animation-');if(animation[1]=="style4")return
if(quote.animation){quote.animation.progress(1).kill();quote.split.revert();}
quote.split=new SplitText(quote,{type:"lines,words",linesClass:"split-line"});gsap.set(quote,{perspective:400});if(animation[1]=="style1"){gsap.set(quote.split.words,{opacity:0,y:"90%",rotateX:"-40deg"});}
if(animation[1]=="style2"){gsap.set(quote.split.words,{opacity:0,x:"50"});}
if(animation[1]=="style3"){gsap.set(quote.split.words,{opacity:0,});}
quote.animation=gsap.to(quote.split.words,{scrollTrigger:{trigger:quote,start:"top 90%",},x:"0",y:"0",rotateX:"0",opacity:1,duration:1,ease:Back.easeOut,stagger:.02});});},"(max-width:1024px)":function(){ScrollTrigger.getAll().forEach(animation=>animation.kill(true));}});}
jQuery(document).ready(function(){pbmit_title_animation();});jQuery(window).resize(function(){pbmit_title_animation();});